-- DATA END

local W, H = SCREEN_W, SCREEN_H
local CAM = {0, 1.0, -3.0}
local PANEL = 84                       -- the tool panel's width
local TOOLS = {"Vertex", "Face", "Color", "Move"}
local cursor = {x = W // 2, y = H // 2}
local finished, spin, drag_x = false, 0, nil

local function ease(t) return t * t * (3 - 2 * t) end
local function lerp(a, b, t) return a + (b - a) * t end

-- time of each part: big parts take longer
local function schedule()
  local t = 1.5
  for i, p in ipairs(PARTS) do
    local nf = #p[3] // 3
    p.t, p.d = t, 0.55 + math.min(nf, 200) / 200 * 1.1
    t = t + p.d
  end
  return t
end

local function build_mesh(p)
  local v, f = {}, {}
  for i, n in ipairs(p[2]) do v[i] = n / 1000 end
  for i = 1, #p[3], 3 do
    local k = #f
    f[k + 1], f[k + 2], f[k + 3], f[k + 4] = p[3][i], p[3][i + 1], p[3][i + 2], p[1]
  end
  return mesh(v, f)
end

local function vpos(p, i)              -- vertex i of a part, in the world
  return p[2][i * 3 - 2] / 1000, p[2][i * 3 - 1] / 1000, p[2][i * 3] / 1000
end

local function screen_of(p, i)
  local x, y, z = vpos(p, i)
  local sx, sy = project3d(x, y, z)
  return sx, sy
end

local END_T

function _init()
  screen(W, H)
  mouse(true, false)
  END_T = schedule()
  for i, p in ipairs(PARTS) do
    p.nv = #p[2] // 3
    p.m = build_mesh(p)
    -- the cursor's route on the part: up to 6 vertices spread over the list
    p.route = {}
    local n = math.min(6, p.nv)
    for k = 1, n do p.route[k] = 1 + (k - 1) * (p.nv - 1) // math.max(1, n - 1) end
  end
  camera3d(CAM[1], CAM[2], CAM[3])
  sky3d(0xFFF2D8, 0x9AA8C8, 0x3A3030)
end

local function arrow(x, y, down)
  local c = down and 0xFFD060 or 0xFFFFFF
  tri(x, y, x, y + 14, x + 10, y + 10, c)
  line(x, y, x, y + 14, 0x000000)
  line(x, y, x + 10, y + 10, 0x000000)
  line(x, y + 14, x + 10, y + 10, 0x000000)
end

local function panel(active, label)
  rectfill(0, 0, PANEL, H, 0x20242C)
  print("bm Mesh", 8, 6, 0xFFD060)
  for i, n in ipairs(TOOLS) do
    local y = 34 + (i - 1) * 24
    local on = i == active
    rectfill(6, y, PANEL - 12, 20, on and 0x4060C0 or 0x30343C)
    print(n, 12, y + 2, on and 0xFFFFFF or 0xA0A8B8)
  end
  print(label, 8, H - 40, 0xA0A8B8)
end

-- the current part's edges
local function wire(p)
  local f = p[3]
  for i = 1, #f, 3 do
    local ax, ay = screen_of(p, f[i])
    local bx, by = screen_of(p, f[i + 1])
    local cx, cy = screen_of(p, f[i + 2])
    if ax and bx and cx then
      line(ax, ay, bx, by, 0x80E0FF); line(bx, by, cx, cy, 0x80E0FF); line(cx, cy, ax, ay, 0x80E0FF)
    end
  end
end

function _update()
  if finished then
    local mx, my, b = mouse()
    if mx and (b & 1) == 1 then
      if drag_x then spin = spin + (mx - drag_x) * 0.02 end
      drag_x = mx
    else
      drag_x = nil
      spin = spin + 0.01
    end
  end
end

function _draw()
  cls(0x14161C)
  local t = time()
  local n = 0
  local cur
  for i, p in ipairs(PARTS) do
    if t >= p.t + p.d then n = i elseif t >= p.t then cur = i end
  end
  finished = t >= END_T
  camera3d(CAM[1], CAM[2], CAM[3])
  -- solid parts
  for i = 1, n do
    draw3d(PARTS[i].m, 0, 0, 0, 0, finished and spin or 0, 0, 1, 0)
  end
  local tool, label = 1, ""
  local arrowx, arrowy, down = cursor.x, cursor.y, false
  if cur then
    local p = PARTS[cur]
    local u = (t - p.t) / p.d
    local px, py = screen_of(p, p.route[1])
    px, py = px or cursor.x, py or cursor.y
    if u < 0.30 then                   -- to the part
      local k = ease(u / 0.30)
      arrowx, arrowy = lerp(cursor.x, px, k), lerp(cursor.y, py, k)
      tool, label = 1, "part " .. cur .. "/" .. #PARTS
    elseif u < 0.70 then               -- vertices
      local k = (u - 0.30) / 0.40
      local shown = math.max(1, math.floor(k * p.nv + 0.5))
      for i = 1, shown do
        local sx, sy = screen_of(p, i)
        if sx then circfill(sx, sy, 1, 0xFFD060) end
      end
      local r = math.min(#p.route, 1 + math.floor(k * #p.route))
      arrowx, arrowy = screen_of(p, p.route[r])
      arrowx, arrowy = arrowx or px, arrowy or py
      down = (k * #p.route * 3) % 1 < 0.4
      tool, label = 1, p.nv .. " vertices"
    elseif u < 0.88 then               -- faces
      draw3d(p.m, 0, 0, 0, 0, 0, 0, 1, 0)
      wire(p)
      arrowx, arrowy = screen_of(p, p.route[#p.route])
      arrowx, arrowy = arrowx or px, arrowy or py
      down = true
      tool, label = 2, (#p[3] // 3) .. " faces"
    else                               -- colour
      draw3d(p.m, 0, 0, 0, 0, 0, 0, 1, 0)
      arrowx, arrowy = screen_of(p, p.route[#p.route])
      arrowx, arrowy = arrowx or px, arrowy or py
      tool, label = 3, string.format("color %06X", p[1])
      rectfill(PANEL + 4, H - 20, 14, 14, p[1])
      rect(PANEL + 4, H - 20, 14, 14, 0xFFFFFF)
    end
    cursor.x, cursor.y = arrowx, arrowy
  elseif finished then
    tool, label = 4, "done: drag to turn"
    local mx, my = mouse()
    if mx then cursor.x, cursor.y = mx, my end
    arrowx, arrowy = cursor.x, cursor.y
  end
  panel(tool, label)
  -- progress bar
  rectfill(PANEL, H - 4, (W - PANEL) * math.min(1, t / END_T), 4, 0x4060C0)
  if t < 1.5 then
    print("KRATOS", W // 2 - 50, 20, 0xFFFFFF, 2)
    print("built with bm Mesh", W // 2 - 70, 54, 0xA0A8B8)
  end
  if finished then print("KRATOS", PANEL + 8, 6, 0xFFFFFF, 2) end
  arrow(arrowx, arrowy, down)
end
